import networkx as nx
from itertools import combinations
import random

def get_gamma_t(G):
    nodes = list(G.nodes())
    n = len(nodes)
    adj = {u: set(G.neighbors(u)) for u in nodes}
    for k in range(2, n + 1):
        for S in combinations(nodes, k):
            S_set = set(S)
            if all(adj[v] & S_set for v in nodes):
                return k
    return None

# For trees, radius <= total_domination_number?
# Let's test random trees of sizes up to 16
for n in range(8, 17):
    for _ in range(500):
        T = nx.random_labeled_tree(n)
        rad = nx.radius(T)
        gt = get_gamma_t(T)
        if rad > gt:
            print(f'Counterexample! n={n}, rad={rad}, gt={gt}')
            print('Edges:', list(T.edges()))
            exit(0)
    print(f'Done random trees n={n}')
